package com.example.redsoportex.feature.lending;
import android.os.Bundle;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;
import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.navigation.fragment.NavHostFragment;
import com.example.redsoportex.R;import com.example.redsoportex.core.ui.BaseFragment;import com.example.redsoportex.databinding.FragmentLoanDetailBinding;import com.example.redsoportex.demo.DemoStore;import com.google.android.material.snackbar.Snackbar;
public class LoanDetailFragment extends BaseFragment<FragmentLoanDetailBinding> implements LoanDetailContract.View {
    private LoanDetailContract.Presenter presenter;
    @NonNull @Override protected FragmentLoanDetailBinding createBinding(@NonNull LayoutInflater i,@Nullable ViewGroup c){return FragmentLoanDetailBinding.inflate(i,c,false);}
    @Override public void onViewCreated(@NonNull View v,@Nullable Bundle state){super.onViewCreated(v,state);getBinding().toolbar.tvTitulo.setText(DemoStore.get().isDonorMode()?R.string.request_detail:R.string.loan_detail_title);getBinding().toolbar.btnVolver.setOnClickListener(x->close());presenter=new LoanDetailPresenter(this);presenter.load(requireArguments().getString("loanId"));getBinding().btnConfirm.setOnClickListener(x->{presenter.advance();Snackbar.make(getBinding().getRoot(),R.string.demo_action,Snackbar.LENGTH_SHORT).show();});getBinding().btnReport.setOnClickListener(x->{Bundle b=new Bundle();b.putString("loanId",requireArguments().getString("loanId"));NavHostFragment.findNavController(this).navigate(R.id.incidentFormFragment,b);});}
    @Override public void showLoan(DemoStore.Loan l,DemoStore.Item i){int st=l.status.equals("PENDING")?R.string.status_pending:l.status.equals("ACTIVE")?R.string.status_active:R.string.status_returned;getBinding().tvStatus.setText(st);getBinding().tvLoanTitle.setText(i.title);getBinding().tvRequester.setText(R.string.requester);getBinding().tvDuration.setText(getString(R.string.loan_days_format,l.days));getBinding().tvReturn.setVisibility(View.GONE);getBinding().tvNotes.setText(l.notes.isEmpty()?getString(R.string.no_notes):l.notes);getBinding().btnConfirm.setVisibility(l.status.equals("RETURNED")?View.GONE:View.VISIBLE);getBinding().btnConfirm.setText(l.status.equals("ACTIVE")?R.string.confirm_return:R.string.confirm_handover);}
    @Override public void close(){NavHostFragment.findNavController(this).navigateUp();}
    @Override public void onDestroyView(){if(presenter!=null){presenter.detachView();presenter=null;}super.onDestroyView();}
}
